statement.p:
The conversion formulas are
\boxed{ x=r\cos\theta,\qquad y=r\sin\theta,\qquad z=z. }
Also,
\boxed{ r^2=x^2+y^2. }

image.asymptote:
import three;
size(9cm);
currentprojection=orthographic(7,-10,7);
real radius=2, theta=pi/4, height=2.6;
triple B=(radius*cos(theta),radius*sin(theta),0);
triple P=(radius*cos(theta),radius*sin(theta),height);
path3 ring=(radius,0,0);
for(int k=1; k<72; ++k) {
  real t=2pi*k/72;
  ring=ring--(radius*cos(t),radius*sin(t),0);
}
ring=ring--cycle;
draw(surface(ring),rgb(0.66,0.79,0.89)+opacity(0.16));
draw(ring,gray(0.62)+linewidth(0.6pt));
draw(O--(3.1,0,0),gray(0.42),Arrow3);
draw(O--(0,3.1,0),gray(0.42),Arrow3);
draw(O--(0,0,3.5),gray(0.42),Arrow3);
label("$x$",(3.1,0,0),2E);
label("$y$",(0,3.1,0),2N);
label("$z$",(0,0,3.5),2N);
draw(O--B,rgb(0.16,0.38,0.73)+linewidth(1.3pt),Arrow3);
label("$r$",0.5*B,2S,rgb(0.16,0.38,0.73));
draw(B--P,rgb(0.77,0.27,0.12)+linewidth(1.4pt),Arrow3);
label("$z$",0.5*(B+P),2E,rgb(0.77,0.27,0.12));
path3 angle=(0.6,0,0);
for(int k=1; k<16; ++k) {
  real t=theta*k/15;
  angle=angle--(0.6*cos(t),0.6*sin(t),0);
}
draw(angle,gray(0.25)+linewidth(0.8pt));
label("$\theta$",(0.8*cos(theta/2),0.8*sin(theta/2),0),2N);
dot(B); dot(P);
label("$(r,\theta,z)$",P,2E);

        // 3-D interactive (WebGL) surface.
import graph3;
        size(7cm);
        currentprojection=orthographic(5,4,3);
        real a=1.2,h=2.6;
        surface s=surface(new triple(pair t){return (a*cos(t.x), a*sin(t.x), t.y);},(0,0),(2pi,h),32,10);
        draw(s, rgb(0.35,0.70,0.90)+opacity(0.85), meshpen=rgb(0.10,0.35,0.50)+linewidth(0.2pt));
        draw(O--(2.0,0,0),gray,Arrow3); draw(O--(0,2.0,0),gray,Arrow3); draw(O--(0,0,3.2),gray,Arrow3);
        label("$x$",(2.0,0,0),S); label("$y$",(0,2.0,0),E); label("$z$",(0,0,3.2),N);

        // 3-D interactive (WebGL) surface.
import graph3;
        size(7cm);
        currentprojection=orthographic(5,4,3);
        real R=2;
        surface s=surface(new triple(pair t){real r=t.y; return (r*cos(t.x), r*sin(t.x), r);},(0,0),(2pi,R),32,12);
        draw(s, rgb(0.95,0.55,0.35)+opacity(0.85), meshpen=rgb(0.50,0.22,0.10)+linewidth(0.2pt));
        draw(O--(2.0,0,0),gray,Arrow3); draw(O--(0,2.0,0),gray,Arrow3); draw(O--(0,0,2.8),gray,Arrow3);
        label("$x$",(2.0,0,0),S); label("$y$",(0,2.0,0),E); label("$z$",(0,0,2.8),N);

import three;
size(9cm);
currentprojection=orthographic(7,-10,7);
real rho=3, theta=pi/4, phi=pi/3;
real radius=rho*sin(phi);
triple B=(radius*cos(theta),radius*sin(theta),0);
triple P=(radius*cos(theta),radius*sin(theta),rho*cos(phi));
path3 ring=(radius,0,0);
for(int k=1; k<72; ++k) {
  real t=2pi*k/72;
  ring=ring--(radius*cos(t),radius*sin(t),0);
}
draw(ring--cycle,gray(0.68)+linewidth(0.6pt));
draw(O--(3.5,0,0),gray(0.42),Arrow3);
draw(O--(0,3.5,0),gray(0.42),Arrow3);
draw(O--(0,0,3.8),gray(0.42),Arrow3);
label("$x$",(3.5,0,0),2E);
label("$y$",(0,3.5,0),2N);
label("$z$",(0,0,3.8),2N);
draw(O--P,rgb(0.15,0.38,0.72)+linewidth(1.5pt),Arrow3);
label("$\rho$",0.60*P,2W,rgb(0.15,0.38,0.72));
draw(O--B,gray(0.45)+linetype("4 3"));
draw(B--P,gray(0.45)+linetype("4 3"));
label("$\rho\sin\phi$",0.55*B,2S);
path3 azimuth=(0.62,0,0);
for(int k=1; k<16; ++k) {
  real t=theta*k/15;
  azimuth=azimuth--(0.62*cos(t),0.62*sin(t),0);
}
draw(azimuth,rgb(0.72,0.28,0.12)+linewidth(0.9pt));
label("$\theta$",(0.88*cos(theta/2),0.88*sin(theta/2),0),2S);
path3 polar=(0,0,0.9);
for(int k=1; k<20; ++k) {
  real t=phi*k/19;
  polar=polar--(0.9*sin(t)*cos(theta),0.9*sin(t)*sin(theta),0.9*cos(t));
}
draw(polar,rgb(0.45,0.25,0.68)+linewidth(0.9pt));
label("$\phi$",(1.15*sin(phi/2)*cos(theta),1.15*sin(phi/2)*sin(theta),1.15*cos(phi/2)),2E);
dot(B); dot(P);
label("$(\rho,\theta,\phi)$",P,2E);

subsection.p:
For converting from rectangular to spherical, the main formulas are
\boxed{ \rho^2=x^2+y^2+z^2, }
\boxed{ \tan\theta=\frac{y}{x} \quad\text{with the quadrant checked carefully}, }
and
\boxed{ \cos\phi=\frac{z}{\rho} \quad(\rho\neq0). }

As always, angle formulas need care. The equation
\tan\theta=\frac{y}{x}
does not determine the quadrant by itself.
